import pathlib
def configure(path,listen_port,dest_port):
    target=pathlib.Path(path)
    if target.is_symlink() or not target.is_file() or any(type(p) is not int or not 1024<=p<=65535 for p in (listen_port,dest_port)):raise ValueError('real config and unprivileged integer ports required')
    original=target.read_text(encoding='utf8');lines=original.splitlines(keepends=True)
    if sum(line.strip()=='Host of-tunnel' for line in lines)!=1:raise ValueError('one approved literal Host block required')
    active=False;output=[]
    for line in lines:
        fields=line.split()
        if fields and fields[0].lower() in ('host','match'):
            active=line.strip()=='Host of-tunnel';output.append(line)
            if active:output.extend([f'  LocalForward 127.0.0.1:{listen_port} 127.0.0.1:{dest_port}\n','  ExitOnForwardFailure yes\n','  GatewayPorts no\n'])
            continue
        if active and fields and fields[0].lower() in ('localforward','exitonforwardfailure','gatewayports'):continue
        output.append(line)
    target.write_text(''.join(output),encoding='utf8')
```

原题知识说明：
SSH 本地转发把客户端监听端口经 SSH 连到服务器侧目标，远程转发在服务器侧监听并回到客户端侧目标，动态转发提供 SOCKS 代理。应限制监听地址和可访问目标，核对两端授权及连接方向；隧道成功不表示最终应用认证成功。

